 v_asset public.verified_question_visual_assets%rowtype; v_asset_id uuid; v_asset_info jsonb;
begin
 select data into v_data from audit_release_input;
 perform pg_advisory_xact_lock(hashtext(v_data->>'version'));
 for v_entry in select value from jsonb_array_elements(v_data->'repairs') loop
  select * into strict v_old from public.questions where id=(v_entry->>'original_id')::uuid for update;
  if v_old.current_content_hash<>v_entry->>'original_hash' then raise exception 'audit_source_content_changed:%',v_old.id;end if;
  if exists(select 1 from public.verified_question_content_repairs where original_question_id=v_old.id and repair_key=v_data->>'version') then continue;end if;
  if not v_old.is_active then raise exception 'audit_source_inactive:%',v_old.id;end if;
  v_id:=(v_entry->>'replacement_id')::uuid;v_patch:=v_entry->'patch';
  v_row:=to_jsonb(v_old)||v_patch||jsonb_build_object('id',v_id,'created_at',now(),'updated_at',now(),
   'content_version',v_data->>'version','content_revision',v_old.content_revision+1,'times_answered',0,'times_correct',0,
   'verified_external_id',case when v_old.verified_external_id is null then null else 'audit-2026-10-12-'||v_id::text end);
  if v_old.subject='English' and v_old.lang='ru' then v_row:=v_row||jsonb_build_object('lang','en');end if;
  v_row:=v_row||jsonb_build_object('accepted_answers',jsonb_build_array(v_row->>'correct_answer'));
  if v_old.verification_status='verified' then
   v_row:=v_row||jsonb_build_object('verified_at',now(),'verified_by_authority','Brains Heist Content Quality',
    'verified_content_hash',private.question_content_hash(v_id,v_row->>'question_text',v_row->'options',v_row->>'correct_answer',v_row->>'explanation',v_row->>'image_url',v_row->>'question_type'));
  end if;
  v_new:=jsonb_populate_record(null::public.questions,v_row);
  insert into public.questions select (v_new).*;
  select * into strict v_new from public.questions where id=v_id;
  for v_item in select * from public.curriculum_assessment_items where source_type='question_bank' and source_record_id=v_old.id::text and content_hash=v_old.current_content_hash loop
   v_new_item:=gen_random_uuid();
   insert into public.curriculum_assessment_items(id,source_type,school_id,source_record_id,source_item_key,source_version,academic_subject_id,grade_level,content_hash,source_metadata,is_active,registered_by)
    values(v_new_item,v_item.source_type,v_item.school_id,v_id::text,v_item.source_item_key,v_data->>'version',v_item.academic_subject_id,v_item.grade_level,v_new.current_content_hash,
     v_item.source_metadata||jsonb_build_object('auditRepairKey',v_data->>'version','supersedesQuestionId',v_old.id),true,v_item.registered_by);
   insert into audit_new_items values(v_item.id,v_new_item);
   for v_map in select * from public.curriculum_item_objective_mappings where assessment_item_id=v_item.id and status='approved' and superseded_at is null and item_content_hash=v_old.current_content_hash loop
    v_new_map:=gen_random_uuid();
    insert into public.curriculum_item_objective_mappings select (jsonb_populate_record(null::public.curriculum_item_objective_mappings,
     to_jsonb(v_map)||jsonb_build_object('id',v_new_map,'assessment_item_id',v_new_item,'item_content_hash',v_new.current_content_hash,
      'provenance',v_map.provenance||jsonb_build_object('auditRepairKey',v_data->>'version','supersedesQuestionId',v_old.id,'sourceMappingId',v_map.id),
      'created_at',now(),'updated_at',now(),'supersedes_mapping_id',null,
      'rationale','Content-quality repair retains the current approved objective; the assessed construct and grade scope are unchanged.'))).*;
    insert into audit_new_mappings values(v_map.id,v_new_map);
   end loop;
  end loop;
  for v_tx in select * from public.verified_question_registry_taxonomy where question_id=v_old.id and question_content_hash=v_old.current_content_hash and review_status='approved' loop
   insert into public.verified_question_registry_taxonomy select (jsonb_populate_record(null::public.verified_question_registry_taxonomy,
    to_jsonb(v_tx)||jsonb_build_object('id',gen_random_uuid(),'question_id',v_id,'question_content_hash',v_new.current_content_hash,
     'source_method','immutable_audit_repair','reviewed_by_authority','Brains Heist Content Quality','reviewed_at',now(),'created_at',now(),'taxonomy_hash',''))).*;
  end loop;
  -- The registry is the current authority. Do not republish legacy taxonomy rows
  -- which predate the required governed evidence-focus fields.
  for v_diag in select * from public.verified_question_diagnostic_taxonomy where question_id=v_old.id and question_content_hash=v_old.current_content_hash and review_status='approved' and not human_review_required
   and nullif(trim(evidence_focus_code),'') is not null and nullif(trim(evidence_focus_name),'') is not null
   and lower(trim(atomic_subskill_name)) not in (lower(trim(v_new.topic)),lower(trim(v_new.curriculum_strand))) loop
   select new_id into v_new_item from audit_new_items where old_id=v_diag.assessment_item_id;
   select new_id into v_new_map from audit_new_mappings where old_id=v_diag.curriculum_mapping_id;
   if v_new_item is null or v_new_map is null then raise exception 'audit_missing_diagnostic_mapping:%',v_old.id;end if;
   insert into public.verified_question_diagnostic_taxonomy select (jsonb_populate_record(null::public.verified_question_diagnostic_taxonomy,
    to_jsonb(v_diag)||jsonb_build_object('id',gen_random_uuid(),'question_id',v_id,'question_content_hash',v_new.current_content_hash,
     'assessment_item_id',v_new_item,'curriculum_mapping_id',v_new_map,'package_version',v_data->>'version',
     'reviewed_by_authority','Brains Heist Content Quality','reviewed_at',now(),'created_at',now(),
     'supersedes_taxonomy_id',null,'taxonomy_hash',null,'review_reason','Immutable content-quality repair preserves the approved atomic skill and evidence focus.'))).*;
  end loop;
  -- New image bytes are deployed first. Record a new immutable asset under the existing release.
  select * into v_asset from public.verified_question_visual_assets where id in(select visual_asset_id from public.verified_question_visual_links where question_id=v_old.id) limit 1;
  if v_asset.id is not null then
   if v_old.image_url is distinct from v_new.image_url then
    select value into v_asset_info from jsonb_array_elements(v_data->'assets') where (value->>'n')::integer=(v_entry->>'n')::integer;
    if v_asset_info is null then raise exception 'audit_asset_manifest_missing:%',v_old.id;end if;
    v_asset_id:=gen_random_uuid();
    insert into public.verified_question_visual_assets select (jsonb_populate_record(null::public.verified_question_visual_assets,
     to_jsonb(v_asset)||jsonb_build_object('id',v_asset_id,'asset_id','audit-2026-10-12-'||(v_entry->>'n'),
      'source_file',v_asset_info->>'path','public_path','/'||replace(v_asset_info->>'path','public/',''),
      'public_url',v_new.image_url,'sha256',v_asset_info->>'sha256','alt_text',v_new.image_alt_text,
      'source','Brains Heist Visual System','created_at',now()))).*;
   else v_asset_id:=v_asset.id;end if;
   insert into public.verified_question_visual_links(question_id,visual_asset_id) values(v_id,v_asset_id);
  end if;
  insert into public.verified_question_content_repairs values(v_old.id,v_id,v_data->>'version',v_entry->>'reason',v_old.current_content_hash,v_new.current_content_hash,'Brains Heist Content Quality',now());
  update public.questions set is_active=false,is_public=false,analytics_eligible=false,
   verification_status=case when pool_scope in('global','school') then 'retired' else verification_status end,updated_at=now() where id=v_old.id;
  insert into audit_release_result values('replaced',v_old.id,v_id);
 end loop;
 for v_entry in select value from jsonb_array_elements(v_data->'retirements') loop
  select * into strict v_old from public.questions where id=(v_entry->>'id')::uuid for update;
  if v_old.current_content_hash<>v_entry->>'hash' then raise exception 'audit_retirement_content_changed:%',v_old.id;end if;
  update public.questions set is_active=false,is_public=false,analytics_eligible=false,
   verification_status=case when pool_scope in('global','school') then 'retired' else verification_status end,updated_at=now() where id=v_old.id;
  if v_entry->>'canonical_id' is not null then
   insert into public.verified_question_duplicate_reviews(duplicate_question_id,canonical_question_id,review_key,review_reason,canonical_reference_count,duplicate_reference_count,reviewed_by_authority)
    values(v_old.id,(v_entry->>'canonical_id')::uuid,v_data->>'version',v_entry->>'reason',
     (select count(*) from public.assignment_questions where question_id=(v_entry->>'canonical_id')::uuid),
     (select count(*) from public.assignment_questions where question_id=v_old.id),'Brains Heist Content Quality') on conflict do nothing;
  end if;
  insert into audit_release_result values('retired',v_old.id,null);
 end loop;
 for v_entry in select value from jsonb_array_elements(v_data->'metadata') loop
  update public.questions set lang='en',updated_at=now() where id=(v_entry->>'id')::uuid and current_content_hash=v_entry->>'hash' and lang='ru';
 end loop;
 if exists(select 1 from public.assignment_questions having count(*)<>(select n from audit_snapshot_guard)
  or md5(string_agg(assignment_id::text||':'||order_index::text||':'||question_snapshot::text,'|' order by assignment_id,order_index)) is distinct from (select digest from audit_snapshot_guard)) then
  raise exception 'audit_assignment_snapshots_changed';end if;
 if exists(select 1 from audit_release_result r join public.questions q on q.id=r.replacement_id where q.verification_status='verified' and not private.verified_question_has_registry_mapping(q.id)) then
  raise exception 'audit_replacement_registry_invariant_failed';end if;
 select count(*) into v_count from audit_release_result where kind='replaced';
 if v_count<>233 then raise exception 'audit_replacement_count:%',v_count;end if;
 select count(*) into v_count from audit_release_result where kind='retired';
 if v_count<>48 then raise exception 'audit_retirement_count:%',v_count;end if;
end;
$repair$;
set constraints all immediate;
select kind,count(*) as count from audit_release_result group by kind;
commit;
